export const SIZES={petite:{name:'Petite',extra:0,stems:'12–15 stems',dimensions:'28cm wide × 38cm tall',description:'A sweet, compact gesture. Lovely on a bedside table.'},classic:{name:'Classic',extra:20,stems:'20–25 stems',dimensions:'38cm wide × 45cm tall',description:'A generous everyday bouquet. The size shown in our photographs.'},abundant:{name:'Abundant',extra:40,stems:'30–35 stems',dimensions:'48cm wide × 55cm tall',description:'A full, room-brightening arrangement for a grand gesture.'}};
export const money = value => new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(value);
export const getProduct=id=>PRODUCTS.find(p=>p.id===id);
export const escapeHtml = value => String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
export function today(now=new Date()) {return new Intl.DateTimeFormat('en-CA',{timeZone:'America/Los_Angeles',year:'numeric',month:'2-digit',day:'2-digit'}).format(now);}
export function addDays(iso,n){const d=new Date(iso+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10);}
export function prettyDate(iso){return new Intl.DateTimeFormat('en-US',{weekday:'short',month:'short',day:'numeric',timeZone:'UTC'}).format(new Date(iso+'T12:00:00Z'));}
export function dateStatus(iso,product,now=new Date()) {
  const base=today(now);
  if(!/^\d{4}-\d{2}-\d{2}$/.test(iso)||Number.isNaN(Date.parse(iso+'T12:00:00Z'))||new Date(iso+'T12:00:00Z').toISOString().slice(0,10)!==iso)return 'Choose a delivery date.';
  if(iso<addDays(base,product.lead))return `This bouquet needs ${product.lead} days of preparation. Please choose a later date.`;
  if(iso>addDays(base,30))return 'Please choose a date within the next 30 days.';
  const day=new Date(iso+'T12:00:00Z').getUTCDay();
  if(day===0||day===1)return 'Our sample studio is closed on Sundays and Mondays.';
  if(iso===addDays(base,10))return 'This sample delivery date is fully booked. Please choose another day.';
  return '';
}
export function datesFor(product,now=new Date()){return Array.from({length:29},(_,i)=>{const date=addDays(today(now),i+2);return {date,reason:dateStatus(date,product,now)};});}
export function deliveryFor(zip){const value=String(zip).trim();if(!/^\d{5}$/.test(value))return {ok:false,message:'Enter a 5-digit US ZIP code, such as 97201.'};if(!['97201','97202','97203','97204','97205','97206'].includes(value))return {ok:false,message:'We don’t deliver to this ZIP in our sample area. Try Portland 97201–97206. No charge has been made.'};const fee=['97201','97202'].includes(value)?6:9;return {ok:true,zip:value,fee,message:`You’re in our sample delivery area. ${money(fee)} per bouquet · 9am–6pm on available dates.`};}
export function unitPrice(item){const p=getProduct(item.product);return p.price+SIZES[item.size].extra+(item.vase?18:0);}
export function bagTotals(bag){const subtotal=bag.reduce((n,item)=>n+unitPrice(item)*item.quantity,0),delivery=bag.reduce((n,item)=>n+(deliveryFor(item.zip).fee||0)*item.quantity,0);return {subtotal,delivery,total:subtotal+delivery,count:bag.reduce((n,item)=>n+item.quantity,0)};}
export function sanitizeBag(raw){if(!Array.isArray(raw))return [];return raw.filter(item=>item&&getProduct(item.product)&&Object.hasOwn(SIZES,item.size)&&Number.isInteger(item.quantity)&&item.quantity>0&&item.quantity<=9&&typeof item.date==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(item.date)&&!Number.isNaN(Date.parse(item.date))&&deliveryFor(item.zip).ok).slice(0,30).map((item,index)=>({id:`item-${index}`,product:item.product,size:item.size,quantity:item.quantity,vase:item.vase===true,zip:String(item.zip).trim(),date:item.date,message:String(item.message||'').slice(0,240)}));}
export function filterProducts(filters={},now=new Date()){const nextDate=datesFor(PRODUCTS[0],now).find(d=>!d.reason)?.date;return PRODUCTS.filter(p=>(!filters.occasion||p.occasions.includes(filters.occasion))&&(!filters.budget||p.price<=Number(filters.budget))&&(!filters.color||p.color===filters.color)&&(!filters.availability||(filters.availability==='next'?!dateStatus(nextDate,p,now):datesFor(p,now).some((d,index)=>!d.reason&&index<6))));}
export function recommend({occasion,style,budget}){const affordable=PRODUCTS.filter(p=>p.price<=Number(budget));return affordable.map(p=>({p,score:(p.occasions.includes(occasion)?2:0)+(p.style===style?3:0)})).sort((a,b)=>b.score-a.score||a.p.price-b.p.price).slice(0,2).map(item=>item.p);}
